// Decimal numbers locate subjects, never rank people or levels of progress.
const classifications=[
 {code:'000',name:'IT·디지털',description:'개발, 인공지능, 데이터, 디지털 서비스'},
 {code:'100',name:'과학·연구',description:'자연과학, 실험, 새로운 것을 탐구하는 일'},
 {code:'200',name:'의료·건강',description:'의료, 간호, 보건, 건강을 돌보는 일'},
 {code:'300',name:'교육·학습',description:'교육, 공부법, 전공과 대학의 일상'},
 {code:'400',name:'예술·디자인',description:'디자인, 그림, 음악, 공연과 창작'},
 {code:'500',name:'미디어·콘텐츠',description:'영상, 글쓰기, 방송, 게임과 콘텐츠'},
 {code:'600',name:'경영·경제',description:'기획, 마케팅, 창업, 경제와 비즈니스'},
 {code:'700',name:'사회·공공',description:'행정, 법, 복지, 사람과 사회를 돕는 일'},
 {code:'800',name:'기술·생활',description:'공학, 제조, 건축, 요리와 생활 기술'},
 {code:'900',name:'환경·지역',description:'환경, 생태, 우리 동네와 지역의 일'}
];
const openClassification={code:'open',name:'분야 탐색 중',description:'관심 있는 분야를 아직 찾고 있는 사람들의 이야기'};
const legacyFields={'아직 탐색 중':'분야 탐색 중','디자인·창작':'예술·디자인','과학·기술':'IT·디지털','공부·대학':'교육·학습','일·생활':'환경·지역'};
const normalizeField=value=>legacyFields[value]||value;
function classificationOf(b){const code=b.taxonomyVersion===2?b.classCode:({b1:'400',b2:'open',b3:'000',b4:'300',b5:'900',b6:'100'})[b.id];return classifications.find(c=>c.code===code)||classifications.find(c=>c.name===normalizeField(b.category))||openClassification}
function classificationsOf(b){return [classificationOf(b),...(b.id==='b6'?[classifications.find(c=>c.code==='400')]:[])]}
function bookMatches(b,code){return classificationsOf(b).some(c=>c.code===code)}
function callNumber(b){return (classificationOf(b).code==='open'?'OPEN':classificationOf(b).code)+' · '+b.name.slice(0,1)}

const categories=['전체',...classifications.map(c=>c.name),openClassification.name];
const books=[
 {id:'b1',name:'서윤',affiliation:'시각디자인을 배우는 대학생',title:'좋아하는 게\n일이 될 수\n있을까요?',subtitle:'그림을 그리던 아이, 디자인을 만나다',category:'예술·디자인',tags:['좋아하는 일','진로 고민'],color:0,quote:'잘하는 것보다, 자꾸 하고 싶어지는 것에서 시작했어요.',chapters:[['노트 귀퉁이에 그리던 그림','수업 시간 노트의 여백은 늘 그림으로 가득했어요. 하지만 미술을 전공할 만큼 잘하는지는 자신이 없었죠. 친구가 동아리 포스터를 부탁했을 때 처음으로 내가 만든 것이 누군가에게 쓰이는 기쁨을 알았어요.'],['좋아하는 마음만으로 충분할까','디자인 전공을 고른 뒤에도 모든 과제가 즐겁지는 않았어요. 발표 때마다 다른 사람과 비교했고, 잘 만든 결과만 보여줘야 한다고 생각했죠. 지금은 완성작 옆에 실패한 스케치도 같이 모읍니다. 왜 바꿨는지 설명할 수 있는 게 제 이야기라는 걸 배웠거든요.'],['아직 쓰는 중인 다음 페이지','저도 어떤 디자이너가 될지 정하지 못했어요. 요즘은 동네 가게의 안내문을 관찰하고, 사람들에게 무엇이 읽기 어려운지 물어봐요. 좋아하는 것을 작은 시도로 옮기는 이야기를 함께 나누고 싶어요.']],help:'디자인 전공의 일상, 취미로 시작하는 작은 창작, 전공을 고르며 했던 고민',boundary:'입시 합격이나 취업을 보장하는 상담, 과제 대리 제작은 하지 않아요.'},
 {id:'b2',name:'도현',affiliation:'전공을 다시 탐색하는 대학생',title:'꿈이 없어도\n괜찮은\n출발',subtitle:'정하지 못한 시간도 나의 이야기니까',category:'분야 탐색 중',tags:['아직 모르겠어요','전공 탐색'],color:1,quote:'남들보다 늦은 줄 알았는데, 내 속도를 찾는 시간이었어요.',chapters:[['하고 싶은 일이 없다는 대답','장래희망을 적는 칸이 가장 어려웠어요. 친구들은 구체적인 직업을 말하는데 저는 매번 다른 답을 썼죠. 일단 성적에 맞춰 대학에 들어갔고, 그 뒤에야 제가 어떤 하루를 좋아하는지 묻기 시작했어요.'],['정답 대신 모아 본 작은 경험','한 학기 동안 도서관 봉사, 사진 동아리, 짧은 코딩 수업을 하나씩 해봤어요. 의외로 결과물보다 같이 고민하고 설명하는 시간이 즐거웠어요. 경험마다 좋았던 순간과 힘들었던 순간을 짧게 기록하면서 선택의 기준이 조금씩 생겼어요.'],['모르겠다는 말을 출발점으로','지금도 진로는 하나로 정해지지 않았어요. 그렇지만 나에 대한 질문은 더 구체적이 됐죠. 꿈을 당장 정하기보다 이번 달에 해볼 작은 실험 하나를 같이 찾아보고 싶어요.']],help:'관심사 찾기, 전공을 다시 고민한 경험, 부담 없이 해볼 작은 활동',boundary:'진로 적성 진단이나 전문 심리상담을 대신하지 않아요.'},
 {id:'b3',name:'지안',affiliation:'동네 문제를 살피는 개발자',title:'코드보다\n사람이 먼저\n궁금했어요',subtitle:'동네의 작은 불편에서 시작한 개발',category:'IT·디지털',tags:['개발의 시작','문제 발견'],color:2,quote:'컴퓨터를 잘 다루는 것보다 질문하는 일이 먼저였어요.',chapters:[['첫 프로그램은 버스 시간표','매일 타는 버스가 언제 오는지 궁금해서 작은 시간표 화면을 만들어봤어요. 처음에는 오류투성이였지만 친구 한 명이 편하다고 말해준 날을 기억해요.'],['혼자 해결하려다 멈춘 날','처음 일할 때는 질문하면 실력이 없어 보일까 걱정했어요. 며칠을 붙잡던 문제가 동료와 이야기하니 풀리기도 했죠. 그때부터 모르는 것을 적고 함께 확인하는 습관을 만들었어요.'],['기술을 어디에 쓰고 싶은지','요즘은 지역 행사 안내가 누구에게 어려운지 살펴보고 있어요. 코딩을 시작하는 방법뿐 아니라, 내가 해결하고 싶은 문제를 찾는 과정을 이야기하고 싶어요.']],help:'개발자가 일하는 방식, 처음 만드는 작은 프로젝트, 질문하는 습관',boundary:'취업 보장, 유료 강의 판매, 숙제 대행은 하지 않아요.'},
 {id:'b4',name:'하람',affiliation:'나에게 맞는 공부법을 찾은 대학생',title:'나만의 속도로\n배우는\n연습',subtitle:'비교를 내려놓고 시작한 작은 루틴',category:'교육·학습',tags:['공부 습관','대학 생활'],color:3,quote:'열 시간 계획보다, 지킬 수 있는 삼십 분이 필요했어요.',chapters:[['계획표는 늘 완벽했지만','새 학기가 되면 빈틈없는 계획표를 만들었어요. 하루만 어긋나도 실패한 기분이 들었죠. 남들이 하는 방식을 그대로 따라가다 보니 제게 맞는 방법을 놓치고 있었어요.'],['삼십 분의 작은 약속','친구와 하루에 삼십 분만 같이 공부해봤어요. 끝나고 오늘 이해한 것 한 가지를 말하는 방식이었죠. 적게 했어도 이어갈 수 있다는 경험이 다음 날 다시 책상에 앉게 했어요.'],['공부 말고도 배워가는 것','대학에 와서는 수업을 고르고 모르는 것을 물어보는 방법도 연습 중이에요. 성적 이야기를 넘어, 나에게 맞는 공부의 리듬과 대학의 일상을 나누고 싶어요.']],help:'내가 시도한 공부 루틴, 대학 생활의 일상, 질문하고 도움 받는 경험',boundary:'성적 향상이나 특정 대학 합격을 보장하지 않아요.'},
 {id:'b5',name:'민재',affiliation:'지역에서 일하는 청년 기획자',title:'내가 사는 곳에\n재미있는 일을\n만드는 법',subtitle:'떠나는 것 말고, 여기서 시작하기',category:'환경·지역',tags:['지역의 일','작은 기획'],color:4,quote:'재미있는 일이 없어서, 친구들과 하나 만들어보기로 했어요.',chapters:[['동네에서 할 수 있는 일이 있을까','대학을 졸업하면 큰 도시로 가야 한다고 생각했어요. 우연히 동네 작은 장터를 도우면서, 아는 장소에도 새로운 일이 숨어 있다는 걸 알게 됐어요.'],['열 명이 와도 괜찮은 행사','처음 만든 모임에는 예상보다 적은 사람이 왔어요. 아쉬웠지만, 한 사람씩 이야기를 듣고 다음 모임을 바꿨어요. 큰 성공보다 작게 열고 다시 고치는 법을 배웠죠.'],['일과 생활을 함께 고민하기','지역에서 일하는 게 늘 낭만적이진 않아요. 예산과 시간, 협력 관계를 조율하는 일도 많죠. 내가 사는 곳에서 어떤 경험을 만들 수 있을지 함께 이야기해보고 싶어요.']],help:'작은 모임을 열어본 경험, 지역에서 일하는 일상, 협업할 때의 고민',boundary:'채용 알선, 투자 권유, 외부 유료 프로그램 모집은 하지 않아요.'},
 {id:'b6',name:'수빈',affiliation:'관심사를 연결하는 대학생',title:'한 가지 꿈만\n가져야\n하나요?',subtitle:'음악과 과학 사이, 나다운 연결 찾기',category:'과학·연구',tags:['여러 관심사','선택의 고민'],color:5,quote:'좋아하는 것들이 서로 멀리 떨어져 있을 필요는 없었어요.',chapters:[['과학실과 합주실 사이','과학 실험도 좋고 밴드 연습도 좋았어요. 하나를 선택하면 다른 하나를 포기해야 할 것 같아서 진로 이야기가 부담스러웠죠.'],['연결해보니 다른 질문이 생겼어요','동아리 공연에서 소리가 어떻게 전달되는지 궁금해졌어요. 작은 녹음 실험을 하면서 관심사가 꼭 한 과목이나 직업으로 정리되지 않아도 된다고 느꼈어요.'],['아직 하나로 묶지 않아도','지금도 서로 다른 수업을 들어보고 있어요. 선택이 어려운 마음, 여러 관심사를 부담 없이 이어가는 방법을 같이 이야기하고 싶어요.']],help:'여러 관심사를 가진 고민, 동아리 경험, 작은 탐구 프로젝트',boundary:'전문 적성검사나 심리 진단은 제공하지 않아요.'}
];

const KEY='wonju-library-v1';
const layoutMedia=window.matchMedia('(max-width: 820px)');
const isMobileLayout=()=>layoutMedia.matches;
const defaults=()=>({onboarded:false,role:'mentee',interests:[],saved:[],blocked:[],meetings:[],consultations:[],reports:[],draft:{},published:[],paused:false,account:null,questions:seedQuestions(),hiddenQuestions:[],conversations:[],reviews:[]});
let storageOK=true,state;
try{state={...defaults(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{state=defaults();storageOK=false}
state.interests=[...new Set(state.interests.map(normalizeField))];
let page='library',filter='전체',query='',meetingRole='mentee',selectedInterests=[],onboardingRole='mentee',lastFocus;
const allBooks=()=>[...books,...state.published];
const getBook=id=>allBooks().find(b=>b.id===id);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch{storageOK=false;toast('브라우저 저장이 제한되어 현재 화면에서만 유지돼요.')}}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function openModal(title,content,wide=false){lastFocus=document.activeElement;const d=$('#dialog');if(d.open)d.close();d.style.maxWidth=wide?'760px':'600px';d.innerHTML=`<div class="modal-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-btn" data-action="close" aria-label="창 닫기">${icon('close')}</button></div>${content}`;d.showModal();d.scrollTop=0}
function closeModal(){const d=$('#dialog');d.close();lastFocus?.isConnected&&lastFocus.focus()}
const brand=()=>`<span class="brand"><span class="brand-mark">${icon('book')}</span><span>원주도서관<small>HUMAN STORY LIBRARY</small></span></span>`;
const navs=[['library','library','사람책 둘러보기'],['community','spark','질문·대화'],['shelf','book','나의 책장'],['meetings','calendar','나의 만남'],['studio','pen','나의 책 쓰기'],['help','shield','사서·1:1 상담']];
function render(){
 document.body.classList.toggle('mobile-app',isMobileLayout());
 document.title='원주도서관 · '+(isMobileLayout()?'모바일':'PC');
 const active=navs.find(n=>n[0]===page)?.[2]||(page==='account'?'내 계정·이메일 인증':'이용 안내');
 $('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a href="#library" aria-label="원주도서관 홈">${brand()}</a><div class="caption">MY LIBRARY</div><nav aria-label="주 메뉴">${navs.map(([id,ic,label])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='shelf'&&state.saved.length?`<span class="count">${state.saved.length}</span>`:''}</a>`).join('')}</nav><div class="side-bottom"><div class="mini-note">${icon('heart')}<br><strong>아직 꿈이 없어도 괜찮아요.</strong><p>다른 사람의 한 페이지에서<br>나의 작은 힌트를 찾아보세요.</p></div><button class="side-setting" data-action="interests">${icon('spark')}나의 관심사 바꾸기</button><a class="side-setting" href="#guide">${icon('shield')}이용 안내와 안전 약속</a><div class="version">WONJU · PROTOTYPE 01</div></div></aside><div class="content"><header class="topbar"><div class="breadcrumb">우리 동네 사람책 <span>${active}</span></div><a class="mobile-brand" href="#library">${brand()}</a><div class="top-actions">${versionSwitch()}<button class="demo-badge" data-action="demo-info">체험용 · 가상 데이터</button>${memberAccess()}<a href="#guide" class="icon-btn" aria-label="이용 안내">${icon('settings')}</a></div></header><main id="main" class="page" tabindex="-1">${({library:isMobileLayout()?mobileLibrary:library,shelf:shelf,meetings:meetings,studio:studio,guide:guide,help:helpDesk,community:communityPage,account:accountPage}[page]||library)()}</main></div><nav class="bottom-nav" aria-label="주 메뉴">${navs.filter(n=>n[0]!=='studio').map(([id,ic,label])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(ic)}<span>${({library:'둘러보기',shelf:'내 공간',meetings:'나의 만남',studio:'책 쓰기',help:'사서',community:'질문·대화'})[id]}</span></a>`).join('')}</nav></div>`;
}
function art(n){const shapes=[
 '<path d="M30 130Q55 20 130 45T190 130" fill="none" stroke="currentColor" stroke-width="2"/><path d="M70 145V70l50-25 40 35v65" fill="#e5c4a3"/><path d="M106 145V93h24v52" fill="#214f43"/><circle cx="150" cy="37" r="13" fill="#dbb98a"/>',
 '<path d="M30 145Q40 60 100 72T180 30" stroke="currentColor" stroke-width="2" fill="none" stroke-dasharray="4 7"/><circle cx="103" cy="71" r="31" fill="#b87656" opacity=".55"/><path d="M70 155l45-48 35 48z" fill="#7c8e73"/><circle cx="174" cy="30" r="7" fill="currentColor"/>',
 '<path d="M35 50h125v85H35z M67 135v17h61v-17" fill="none" stroke="currentColor" stroke-width="2"/><path d="M70 75L57 90l13 15 M123 75l13 15-13 15 M106 70l-18 42" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="165" cy="45" r="26" fill="#a6b17d" opacity=".7"/>',
 '<path d="M20 140h155v12H20z M50 125h100v14H50z M40 103h115v20H40z M65 80h65v20H65z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M87 78V28 M87 30q40-15 48 0-22 20-48 10" fill="#f1dcac" stroke="currentColor" stroke-width="1"/>',
 '<path d="M20 145V90l30-30 30 30v55 M85 145V55h45v90 M135 145V77l30-20 25 20v68" fill="none" stroke="currentColor" stroke-width="1.5"/><circle cx="150" cy="25" r="18" fill="#c9a77c"/><path d="M35 112h14v33 M100 70h10 M100 90h10 M148 98h10 M167 98h10" stroke="currentColor"/>',
 '<circle cx="82" cy="80" r="43" fill="#e8d9b9" opacity=".7"/><circle cx="129" cy="89" r="43" fill="none" stroke="currentColor" stroke-width="2"/><path d="M35 147q45-50 95 0" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="158" cy="38" r="7" fill="currentColor"/>'
 ];return `<svg class="cover-art" viewBox="0 0 210 170" aria-hidden="true">${shapes[n%6]}</svg>`}
function cover(b){return `<div class="book-cover cover-${b.color}"><span class="edition">WONJU HUMAN STORY · ${b.id.startsWith('own')?'MY BOOK':String(books.indexOf(b)+1).padStart(2,'0')}</span><h3>${esc(b.title)}</h3><span class="cover-sub">${esc(b.subtitle)}</span>${art(b.color)}<div class="cover-bottom"><b>${esc(b.name)}의 이야기</b><span>${classificationOf(b).code}</span></div></div>`}
function cards(items,reasons=false){return `<div class="book-grid">${items.map(b=>`<article class="book-card"><button class="cover-open" data-action="read" data-id="${b.id}" aria-label="${esc(b.title.replaceAll('\n',' '))} 읽기">${cover(b)}</button><button class="bookmark ${state.saved.includes(b.id)?'saved':''}" data-action="save" data-id="${b.id}" aria-label="${esc(b.name)}의 책 ${state.saved.includes(b.id)?'책장에서 꺼내기':'책장에 담기'}" aria-pressed="${state.saved.includes(b.id)}">${icon('book')}</button><div class="book-info">${rentalBadge(b.id)}<div class="tags"><span>${classificationOf(b).code} ${esc(classificationOf(b).name)}</span><span>·</span><span>${esc(b.tags[0])}</span></div><h3><button class="text-link" data-action="read" data-id="${b.id}">${esc(b.quote)}</button></h3><div class="author"><strong>${esc(b.name)}</strong><span class="dot"></span><span>${esc(b.affiliation)}</span></div>${reasons&&state.interests.length?`<p class="reason">${icon('spark').replace('class="icon"','class="icon" style="width:11px;height:11px;vertical-align:middle"')} ${esc(reason(b))}</p>`:''}</div></article>`).join('')}</div>`}
function reason(b){const match=classificationsOf(b).find(c=>state.interests.includes(c.name));return match?`${match.name}에 관심 있는 나에게`:classificationOf(b).code==='open'?'관심 분야를 아직 찾고 있다면 함께 읽어요':'새로운 관심사를 발견할 수 있는 이야기'}
function score(b){return classificationsOf(b).some(c=>state.interests.includes(c.name))?10:0}
function heroArt(){return `<svg class="hero-art" viewBox="0 0 350 280" aria-hidden="true"><ellipse cx="185" cy="248" rx="140" ry="17" fill="#d6dfcb"/><circle cx="255" cy="75" r="55" fill="#d7e1bf"/><path d="M65 223l-13-84 100-18 14 85z" fill="#c99a78"/><path d="M64 143l79-13 M67 152l79-13" stroke="#ead0b6"/><path d="M95 232l5-143 92 3-5 143z" fill="#234f43"/><path d="M111 99l-4 122" stroke="#b9c4a3"/><path d="M126 131q20-9 39 0v50q-20-8-40 0z M145 127v53" fill="none" stroke="#d4ddb8"/><path d="M196 231l-7-117 79-4 7 117z" fill="#e3c895"/><path d="M205 124l52-3 M205 134l52-3" stroke="#8a7658"/><path d="M266 234l-12-57 52-12 13 58z" fill="#98aa81"/><path d="M278 184l22-5 M281 194l22-5" stroke="#eef0da"/><path d="M296 166q-5-52-34-67 M276 126q-28 1-30-20 29-8 30 20 M288 144q-5-29 17-37 11 23-17 37" fill="#7c9569"/><path d="M36 75l3 9 9 3-9 3-3 9-3-9-9-3 9-3z M177 43l2 6 6 2-6 2-2 6-2-6-6-2 6-2z" fill="#a2af8c"/></svg>`}
function versionSwitch(){return `<nav class="version-switch" aria-label="화면 버전"><span aria-current="page">${isMobileLayout()?'모바일':'PC'}</span><a href="./${isMobileLayout()?'desktop':'mobile'}.html" target="_top" aria-label="${isMobileLayout()?'PC':'모바일'} 버전 열기">${isMobileLayout()?'PC':'모바일'}</a></nav>`}
function mobileLibrary(){
 const popular=['000','400','300','900'];
 if(filter!=='전체'&&filter!=='open'&&!popular.includes(filter))popular.unshift(filter);
 return `<section class="mobile-greeting"><div class="eyebrow">MY NEIGHBORHOOD LIBRARY</div><h1>오늘은 어떤 이야기가<br>궁금한가요?</h1><p>관심 있는 분야의 사람책을 꺼내보세요.<br>한 사람의 경험이 나의 다음 페이지가 될 거예요.</p><div class="mobile-greeting-footer"><span>${icon('book')} 우리 동네 사람책 ${allBooks().filter(b=>!state.blocked.includes(b.id)).length}권</span><button data-action="filter" data-value="open">아직 관심 분야를 모르겠어요 ${icon('arrow').replace('class="icon"','class="icon" style="width:12px;height:12px;vertical-align:middle"')}</button></div></section><section aria-label="모바일 사람책 서가"><div class="mobile-catalog-tools"><form id="search-form" class="search-row" role="search"><label class="search">${icon('search')}<input id="search-input" aria-label="사람책 검색" placeholder="어떤 분야, 어떤 이야기가 궁금한가요?" value="${esc(query)}" enterkeyhint="search"><button type="submit" aria-label="검색">${icon('arrow')}</button></label></form><div class="mobile-field-scroll" aria-label="사람책 분야"><button class="${filter==='전체'?'active':''}" data-action="filter" data-value="전체" aria-pressed="${filter==='전체'}">전체 서가</button><button class="all-fields" data-action="classification-guide">${icon('library')} 전체 분야</button>${popular.map(code=>{const c=classifications.find(c=>c.code===code);return `<button class="${filter===code?'active':''}" data-action="filter" data-value="${code}" aria-pressed="${filter===code}"><b>${code}</b>${c.name}</button>`}).join('')}${filter==='open'?'<button class="active" data-action="filter" data-value="open" aria-pressed="true">분야를 찾는 중</button>':''}</div></div>${mentorFilters()}<div id="results">${libraryResults()}</div></section><div class="closing-note">${icon('shield')}<div><strong>내가 고르고, 서로 동의하고, 안전하게 만나요.</strong><br>가상 인물·장소로 체험해요. 실제 신청은 전송되지 않아요.</div></div>`;
}
function library(){return `<section class="library-welcome"><div><div class="eyebrow">THE HUMAN STORY LIBRARY</div><h1>사람을 읽는 시간,<br class="mobile-break"> 나를 발견하는 책장.</h1><p>책장 사이를 천천히 걸으며, 마음이 가는 한 권을 꺼내보세요.</p></div><button class="classification-link" data-action="classification-guide">${icon('library')}<span>사람책 분류표<small>000 — 900</small></span>${icon('arrow')}</button></section><section aria-labelledby="explore-title"><div class="library-toolbar"><h2 id="explore-title">우리 동네 사람책 서가</h2><button class="text-link" data-action="interests">${icon('spark')} 나의 관심사</button></div><form id="search-form" class="search-row" role="search"><label class="search">${icon('search')}<input id="search-input" aria-label="사람책 검색" placeholder="책 제목, 관심사 또는 분류번호로 찾아보세요" value="${esc(query)}"><button type="submit" aria-label="검색">${icon('arrow')}</button></label></form><div class="filter decimal-filter" aria-label="사람책 분류"><button class="chip ${filter==='전체'?'active':''}" data-action="filter" data-value="전체" aria-pressed="${filter==='전체'}">전체 서가</button>${classifications.map(c=>`<button class="chip ${filter===c.code?'active':''}" data-action="filter" data-value="${c.code}" aria-pressed="${filter===c.code}"><b>${c.code}</b>${c.name}</button>`).join('')}<button class="chip ${filter==='open'?'active':''}" data-action="filter" data-value="open" aria-pressed="${filter==='open'}">아직 분야를 찾는 중</button></div>${mentorFilters()}<div id="results">${libraryResults()}</div></section><div class="closing-note">${icon('shield')}<div><strong>이야기는 자유롭게 고르고, 만남은 안전한 공간에서.</strong><br>가상 인물·장소로 구성한 체험용 도서관이에요. 책을 누르면 이야기가 펼쳐져요.</div></div>`}
function libraryResults(){
 let list=allBooks().filter(b=>!state.blocked.includes(b.id)).filter(mentorMatches).filter(b=>(filter==='전체'||bookMatches(b,filter))&&(!query||[b.title,b.subtitle,b.name,b.affiliation,b.category,...classificationsOf(b).flatMap(c=>[c.name,c.code]),...b.tags,b.quote,...Object.values(mentorInfo(b)).flat()].join(' ').toLowerCase().includes(query.toLowerCase())));
 list.sort((a,b)=>classificationOf(a).code.localeCompare(classificationOf(b).code)||a.name.localeCompare(b.name,'ko'));
 const count=list.length;
 const recommended=state.interests.length?[...list].sort((a,b)=>score(b)-score(a)).filter(b=>score(b)>0).slice(0,3):[];
 return `${filter==='전체'&&!query&&Object.values(mentorCriteria).every(v=>v==='전체')?featuredShelves():''}${recommended.length?`<div class="recommend-strip">${icon('spark')}<div>오늘의 관심사와 닿은 책<span>관심사로 연결한 추천 체험 · 서가에서는 분류번호 순으로 꽂혀 있어요.</span></div><button data-action="read" data-id="${recommended[0].id}">${esc(recommended[0].name)}의 책 읽기</button></div>`:''}<div class="result-meta"><span>${filter==='전체'?'전체 서가':(classifications.find(c=>c.code===filter)||openClassification).name} · 사람책 <strong>${count}</strong>권</span><span>좌우로 밀고, 책등을 눌러 읽어요</span></div>${count?bookshelves(list):empty('search','이 칸은 아직 다음 이야기를 기다려요',query?'다른 단어나 분류번호로 찾아볼까요?':'다른 서가의 사람책을 먼저 만나보세요.','전체 서가로 돌아가기','clear-search')}`;
}
function bookshelves(list){
 const sections=[{min:0,max:299,range:'000—299',name:'디지털·과학·건강',note:'궁금한 분야에서<br>나의 다음 질문을 찾아요.',sub:'IT · 과학 · 의료'}, {min:300,max:599,range:'300—599',name:'교육·예술·콘텐츠',note:'좋아하는 일이<br>어떤 하루가 되는지.',sub:'교육 · 창작 · 미디어'}, {min:600,max:999,range:'600—999',name:'경영·사회·기술·환경',note:'일하는 사람의 경험에서<br>관심 분야를 넓혀보세요.',sub:'경영 · 공공 · 기술 · 지역'}, {min:0,max:0,range:'OPEN',name:'아직 관심 분야를 찾는 중',note:'분야가 정해지지 않아도,<br>이야기부터 시작해요.',sub:'자유롭게 둘러보기',open:true}];
 return `<div class="library-bookcase">${sections.map((g,i)=>{const bs=list.filter(b=>g.open?classificationOf(b).code==='open':classificationOf(b).code!=='open'&&Number(classificationOf(b).code)>=g.min&&Number(classificationOf(b).code)<=g.max);if(!bs.length)return '';return `<section class="shelf-bay" aria-labelledby="shelf-${i}"><div class="shelf-heading"><span class="shelf-range">${g.range}</span><h3 id="shelf-${i}">${g.name}</h3><span class="shelf-count">${bs.length} BOOKS</span><div class="shelf-motion-controls" aria-label="책 슬라이드"><button data-shelf-step="-1" aria-label="${g.name} 책을 오른쪽으로 밀기">${icon('arrow')}</button><button data-shelf-step="1" aria-label="${g.name} 책을 왼쪽으로 밀기">${icon('arrow')}</button></div></div><div class="shelf-interior"><div class="shelf-scroll" tabindex="0" role="group" aria-label="${g.name}의 책들. 가로로 넘겨볼 수 있어요."><div class="standing-books">${bs.map((b,j)=>spine(b,j)).join('')}<div class="bookend" aria-hidden="true"></div></div></div><div class="shelf-poem" aria-hidden="true"><span>${g.sub}</span><p>${g.note}</p><svg viewBox="0 0 90 45"><path d="M2 40q20-35 40 0 20-35 40 0M44 40V3" fill="none" stroke="currentColor" stroke-width="1"/></svg></div></div><div class="wood-ledge"><span>WONJU HUMAN STORY LIBRARY</span><span>서가 ${String(i+1).padStart(2,'0')}</span></div></section>`}).join('')}</div>`;
}
function spine(b,j){const c=classificationOf(b);const saved=state.saved.includes(b.id);return `<article class="shelved-book ${bookRentals(b.id).length?'has-rental':''}" style="--book-height:${[222,238,214,230][j%4]}px">${rentalBadge(b.id,true)}<button class="book-spine cover-${b.color}" data-action="read" data-id="${b.id}" aria-label="${esc(c.code+' '+c.name+', '+b.title.replaceAll('\n',' ')+', '+b.name+'의 사람책 읽기')}"><span class="spine-bands" aria-hidden="true"></span><span class="spine-title ${b.title.length>20?'long':''}">${esc(b.title.replaceAll('\n',' ').length>26?b.title.replaceAll('\n',' ').slice(0,25)+'…':b.title.replaceAll('\n',' '))}</span><span class="spine-author">${esc(b.name)}의 이야기</span><span class="spine-label"><strong>${c.code==='open'?'OPEN':c.code}</strong><span>${esc(b.name.slice(0,1))} · 사람책</span></span></button><button class="shelf-bookmark ${saved?'saved':''}" data-action="save" data-id="${b.id}" aria-label="${esc(b.name)}의 책 ${saved?'책장에서 꺼내기':'책장에 담기'}" aria-pressed="${saved}">${icon('book')}</button><button class="shelf-topic" data-action="filter" data-value="${c.code}" aria-label="${c.code} ${c.name} 서가 보기">${c.code==='open'?'OPEN':c.code}</button></article>`}
function classificationGuide(){const available=allBooks().filter(b=>!state.blocked.includes(b.id));openModal('원주 사람책 분류표',`<div class="modal-body"><div class="eyebrow">A PLACE FOR EVERY STORY</div><h3>관심 있는 분야에서, 사람을 만나요.</h3><p>직업과 흥미 분야를 기준으로 사람책을 모았어요. 관심 있는 분야나 번호를 누르면 관련 경험을 가진 사람의 책을 찾을 수 있어요.</p><div class="classification-table">${classifications.map(c=>{const count=available.filter(b=>bookMatches(b,c.code)).length;return `<button data-action="classification-select" data-value="${c.code}"><b>${c.code}</b><span><strong>${c.name}</strong><small>${c.description}</small></span><em>${count}권</em>${icon('arrow')}</button>`}).join('')}</div><div class="notice">한국십진분류법의 숫자 체계에서 착안한 <strong>앱 전용 사람책 분류</strong>예요. 실제 한국십진분류표의 항목과는 달라요. 직업·흥미 분야를 찾기 위한 위치표예요. 한 책이 여러 분야와 연결될 수 있고, 아직 관심 분야를 모르면 ‘분야를 찾는 중’ 서가에서 시작할 수 있어요.</div><p class="classification-source"><a href="https://www.nl.go.kr/NL/contents/N30501000000.do?ackRecKey=4978992&schM=view" target="_blank" rel="noopener noreferrer">분류 체계 참고 · 국립중앙도서관 ${icon('arrow')}</a></p></div>`,true)}
function empty(ic,title,text,label,action){return `<div class="empty">${icon(ic)}<h3>${title}</h3><p>${text}</p><button class="btn primary" data-action="${action}">${label}${icon('arrow')}</button></div>`}
function shelf(){const list=allBooks().filter(b=>state.saved.includes(b.id)&&!state.blocked.includes(b.id));return `<div class="page-heading"><div class="eyebrow">MY BOOKSHELF</div><h1>마음에 남은 이야기.</h1><p>다시 펼쳐보고 싶은 사람책을 모아두었어요.</p></div>${accountShelfLinks()}<div class="result-meta"><span>나의 책장 <strong>${list.length}</strong>권</span><span>이 브라우저에 저장돼요</span></div>${list.length?cards(list):empty('book','아직 비어 있는 나의 책장','궁금한 책의 책장에 담기 버튼을 누르면 여기에 모여요.','사람책 둘러보기','library')}`}
const personPhotos={b1:'./assets/portraits/b1-portrait.png',b2:'./assets/portraits/b2-portrait.png',b3:'./assets/portraits/b3-portrait.png',b4:'./assets/portraits/b4-portrait.png',b5:'./assets/portraits/b5-portrait.png',b6:'./assets/portraits/b6-portrait.png'};
function readerPortrait(b){const photo=personPhotos[b.id];return photo?`<figure class="reader-portrait"><img src="${photo}" alt="${esc(b.name)}의 AI 생성 가상 프로필 사진" width="400" height="500" decoding="async"><figcaption>AI로 만든 가상 인물</figcaption></figure>`:`<figure class="reader-portrait"><div class="portrait-placeholder">${icon('user')}<span>프로필 사진 미등록</span></div><figcaption>내가 작성한 체험용 책</figcaption></figure>`}
function readBook(id){const b=getBook(id);if(!b)return;openModal('사람책 펼쳐보기',`<div class="modal-body"><div class="reader-intro reader-with-portrait">${readerPortrait(b)}<div><div class="eyebrow">이야기를 들려줄 사람</div><h3 class="reader-title">${esc(b.title.replaceAll('\n',' '))}</h3><div class="reader-person"><strong>${esc(b.name)}</strong>의 이야기<br>${esc(b.affiliation)}<br><span class="draft-tag">${b.id.startsWith('own')?'내가 만든 체험용 책 · 확인 전':'체험용 사람책'}</span></div><div class="reader-tags">${classificationsOf(b).map(c=>`<span>${c.code==='open'?'OPEN':c.code} · ${esc(c.name)}</span>`).join('')}${b.tags.map(t=>`<span># ${esc(t)}</span>`).join('')}</div></div></div>${mentorProfilePanel(b)}${rentalPanel(b.id)}${b.chapters.map((c,i)=>`<section class="chapter"><div class="small-label">CHAPTER 0${i+1}</div><h3>${esc(c[0])}</h3><p>${esc(c[1])}</p></section>`).join('')}<section class="book-boundary"><h4>이런 이야기를 함께 나눌 수 있어요</h4><p>${esc(b.help)}</p><h4 style="margin-top:15px">경험 나눔의 약속</h4><p>${esc(b.boundary)}</p></section>${readerReviews(b.id)}<div class="reader-actions"><button class="btn" data-action="save-reader" data-id="${b.id}" aria-pressed="${state.saved.includes(b.id)}">${icon('book')}<span>${state.saved.includes(b.id)?'책장에 담김':'책장에 담기'}</span></button><button class="btn primary" data-action="book-request" data-id="${b.id}">이 사람과 이야기하기 ${icon('arrow')}</button></div><div class="reader-tools"><button data-action="start-chat" data-id="${b.id}">1:1 대화 시작</button><button data-action="help">사서에게 1:1 상담</button><button data-action="report" data-id="${b.id}">이 책 신고하기</button><button data-action="block" data-id="${b.id}">이 사람의 책 숨기기</button></div></div>`,true)}
function onboarding(){onboardingRole=state.role;openModal('원주도서관에 오신 걸 환영해요',`<div class="modal-body"><div class="eyebrow">YOUR NEXT CHAPTER</div><h3 class="onboarding-title">지금의 나는,<br>어떤 이야기를 찾고 있나요?</h3><p>다 읽을 필요도, 꿈이 정해져 있을 필요도 없어요.<br>오늘의 나에게 가까운 쪽을 골라주세요.</p><div class="role-options"><button class="role-option" data-action="choose-role" data-value="mentee">${icon('book')}<strong>이야기를 읽고 싶어요</strong><span>경험을 읽고, 궁금한 것을 물어요.</span></button><button class="role-option" data-action="choose-role" data-value="mentor">${icon('pen')}<strong>이야기를 나누고 싶어요</strong><span>나의 경험을 한 권의 책으로 써요.</span></button></div><button class="skip-onboarding" data-action="skip-onboarding">아직 잘 모르겠어요 · 먼저 둘러볼게요</button><div class="notice">지금은 체험용 앱이에요. 모든 사람과 장소는 가상이며, 이름·연락처 등 실제 개인정보는 입력하지 마세요.</div></div>`)}
function interests(role=state.role){onboardingRole=role;selectedInterests=[...new Set(state.interests.map(value=>fieldGroup(value)?.name||value))];openModal('나의 관심사',`<div class="modal-body"><div class="eyebrow">FIND YOUR CURIOSITY</div><h3 class="onboarding-title">조금이라도 궁금한 것을<br>골라볼까요?</h3><p>여러 개 골라도, 하나도 고르지 않아도 괜찮아요.<br>관심사는 언제든 바꿀 수 있어요.</p><div class="interest-options">${categories.slice(1).map(c=>`<button class="chip ${selectedInterests.includes(c)?'active':''}" data-action="interest" data-value="${c}" aria-pressed="${selectedInterests.includes(c)}">${c}</button>`).join('')}</div><div class="notice">추천은 선택한 관심사에 따라 책의 순서를 바꾸는 체험이에요. 실제 AI API는 연결하지 않았어요.</div><div class="onboarding-footer"><button class="skip-onboarding" data-action="skip-interests">그냥 둘러볼게요</button><button class="btn primary" data-action="finish-interests">${role==='mentor'?'내 이야기 쓰기':'사람책 만나기'} ${icon('arrow')}</button></div></div>`)}
function finishOnboarding(skip=false){state.onboarded=true;state.role=onboardingRole;state.interests=skip?[]:selectedInterests;persist();closeModal();const target=state.role==='mentor'?'studio':'library';if(page===target)render();else location.hash=target;toast(skip?'나에게 맞는 속도로 둘러보세요.':'좋아요. 오늘의 관심사에서 시작해볼게요.')}
const venues=[{id:'v1',name:'체험용 도서관 열린 대화실',desc:'가상 협력공간 A · 공개된 대화 구역 · 현장 담당자 상주',days:[3,5],hour:16},{id:'v2',name:'체험용 청소년공간 이야기방',desc:'가상 협력공간 B · 직원이 있는 공용 공간',days:[4,6],hour:14}];
function slots(){const result=[];for(let n=1;n<=16;n++){const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()+n);for(const v of venues)if(v.days.includes(d.getDay()))result.push({id:`${d.getFullYear()}-${d.getMonth()+1}-${d.getDate()}-${v.id}`,venue:v.id,date:d.getTime(),label:`${d.getMonth()+1}월 ${d.getDate()}일 (${['일','월','화','수','목','금','토'][d.getDay()]}) ${v.hour}:00–${v.hour+1}:00`})}return result.slice(0,6)}
function requestBook(id,previous=null){
 const b=getBook(id);if(!b)return;if(!requireMember())return;
 if(state.paused){toast('체험용 신청받기가 쉬는 중이에요. 나의 만남 → 멘토로 보기에서 재개할 수 있어요.');return}
 if(id.startsWith('own')){toast('내 책은 신청할 수 없어요. 다른 사람책을 골라주세요.');return}
 if(state.blocked.includes(id)){toast('숨긴 사람책이에요. 이용 안내에서 숨기기를 해제할 수 있어요.');return}
 if(state.meetings.some(m=>m.bookId===id&&m.status==='requested')){toast('이 사람책과 수락을 기다리는 신청이 있어요. 나의 만남에서 확인해요.');return}
 const ss=slots(),available=ss.filter(x=>!rentalConflict(id,dayISO(new Date(x.date)),dayISO(new Date(x.date))));
 openModal(previous?'후속 만남 신청':'이야기 나누기 신청',`<form id="request-form" class="modal-body" data-book="${id}" data-previous="${previous||''}"><div class="eyebrow">LET’S TALK TOGETHER</div><h3>${esc(b.name)}님과 나누고 싶은 이야기</h3><p>서로의 동의가 있어야 만남이 확정돼요.<br>대화는 가상의 지정 공간과 운영 시간 안에서만 진행돼요.</p>${rentalPanel(id)}<label class="field"><span>01. 어떤 이야기가 궁금한가요?</span><select name="topic" required><option value="">주제를 골라주세요</option>${[...b.tags,'나의 작은 시도 함께 생각하기'].map(t=>`<option>${esc(t)}</option>`).join('')}</select></label><label class="field"><span>질문 한 줄 <small>선택 · 이름, 학교, 연락처 등 실제 개인정보를 적지 마세요.</small></span><textarea name="question" maxlength="250" placeholder="예: 좋아하는 일을 찾기 위해 처음 어떤 시도를 했나요?"></textarea></label><div class="step-label">02. 가능한 장소와 시간</div><div class="radio-options">${ss.map(s=>{const v=venues.find(v=>v.id===s.venue),busy=!available.includes(s);return `<label class="radio-option ${busy?'slot-busy':''}"><input type="radio" name="slot" value="${s.id}" required ${busy?'disabled':s===available[0]?'checked':''}><span>${s.label}<small>${v.name} · ${busy?'대여 기간과 겹쳐 신청할 수 없어요':'담당자 상주'}</small></span></label>`}).join('')}</div>${!available.length?'<p class="form-error">현재 열린 일정은 모두 대여 기간과 겹쳐요. 나중에 다시 확인하거나 사서에게 문의해주세요.</p>':''}<div class="notice"><strong>안전하게 만나는 약속</strong><br>체험용 장소이며 실제 협력 관계는 없어요. 실제 운영에서는 확보된 협력시설·시간만 제공하고, 별도 장소나 개인 연락처로 연결하지 않아요.</div><label class="checkline"><input type="checkbox" name="consent" required><span>경험을 나누는 대화임을 이해하며, 서로 존중하고 지정 공간에서 만나는 약속에 동의해요. 실제 신청이 전송되지 않는 체험이에요.</span></label><p id="request-error" class="form-error" role="alert"></p><div class="actions"><button type="button" class="btn" data-action="read" data-id="${id}">책으로 돌아가기</button><button class="btn primary" type="submit" ${!available.length?'disabled':''}>${previous?'후속 만남 신청하기':'만남 신청하기'} ${icon('arrow')}</button></div></form>`)
}
function submitRequest(form){
 if(!form.reportValidity())return;const data=new FormData(form),s=slots().find(x=>x.id===data.get('slot')),id=form.dataset.book;
 const error=$('#request-error');
 if(!s){error.textContent='가능한 시간이 바뀌었어요. 책을 다시 열어 신청해주세요.';return}
 if(state.paused||state.blocked.includes(id)||state.meetings.some(m=>m.bookId===id&&m.status==='requested')){error.textContent='신청 상태가 바뀌었어요. 창을 닫고 나의 만남을 확인해주세요.';return}
 const date=dayISO(new Date(s.date));if(rentalConflict(id,date,date)){error.textContent='선택한 날짜는 대여중이에요. 다른 날짜로 골라주세요.';return}
 const v=venues.find(v=>v.id===s.venue);state.meetings.unshift({id:'m'+Date.now(),bookId:id,status:'requested',topic:data.get('topic'),question:String(data.get('question')||'').trim(),slot:s.label,meetingDate:date,venue:v.name,created:Date.now(),previous:form.dataset.previous||null,checkedIn:false});persist();render();openModal('신청 체험 완료',`<div class="success-body"><div class="success-icon">${icon('check')}</div><h3>새로운 대화의<br>첫 페이지를 열었어요.</h3><p>지금은 멘토의 수락을 기다리는 상태예요.<br>‘나의 만남’에서 멘토 역할로 바꿔 대여 기간을 정하고 수락해보세요.</p><button class="btn primary full" data-action="go-meetings">나의 만남에서 확인하기 ${icon('arrow')}</button><div class="pill-note">브라우저에만 저장된 가상 신청이에요.</div></div>`)
}
const statusText={requested:'수락 기다리는 중',confirmed:'만남 확정',completed:'이야기 나눔 완료',cancelled:'취소된 만남',declined:'수락되지 않은 만남'};
function meetings(){return `<div class="page-heading"><div class="eyebrow">OUR NEXT MEETING</div><h1>이야기에서, 대화로.</h1><p>서로의 동의로 시작하고, 서로의 속도로 이어가요.</p></div><div class="segmented" aria-label="체험 역할"><button data-action="meeting-role" data-value="mentee" class="${meetingRole==='mentee'?'active':''}" aria-pressed="${meetingRole==='mentee'}">멘티로 보기</button><button data-action="meeting-role" data-value="mentor" class="${meetingRole==='mentor'?'active':''}" aria-pressed="${meetingRole==='mentor'}">멘토로 보기 · 체험</button></div><div class="notice">${meetingRole==='mentor'?'체험을 위해 신청을 받은 멘토 역할로 전환했어요. 실제 운영에서는 본인에게 온 신청만 볼 수 있어요. 신청 주제와 시간을 확인하고 수락하거나 거절해보세요.':'신청 → 멘토 수락 → 지정 공간에서 대화 → 원하면 후속 신청으로 이어져요. 일정 변경은 기존 신청을 취소하고 새로 신청할 수 있어요.'}</div>${meetingRole==='mentor'?`<button class="btn soft" data-action="pause">${state.paused?'신규 신청 받기 재개':'신규 신청 받기 잠시 쉬기'}</button><p class="pill-note" style="margin-bottom:20px">${state.paused?'신청받기 일시 중지 체험 중 · 기존 신청에는 답할 수 있어요.':'신청받기 설정 체험 · 가상 멘토 전체에 적용돼요.'}</p>`:''}<div class="meeting-list">${state.meetings.length?state.meetings.map(meetingCard).join(''):empty('calendar','아직 예정된 만남이 없어요','먼저 궁금한 사람책 한 권을 펼쳐볼까요?','사람책 찾아보기','library')}</div>`}
function meetingCard(m){const b=getBook(m.bookId);if(!b)return '';return `<article class="meeting-card"><div class="meeting-mini cover-${b.color}">${esc(b.name)}의 책</div><div><span class="status ${m.status}">${statusText[m.status]}</span>${m.previous?' <span class="draft-tag">후속 만남</span>':''}<h3>${esc(b.name)}님과 ${esc(m.topic)}</h3><p>${esc(m.question||'만나서 함께 이야기해보고 싶어요.')}</p><div class="meeting-meta"><span>${m.slot}</span><span>${m.venue}</span></div>${m.status==='confirmed'?`<div class="meeting-rental">${icon('book')} 대여 기간 · ${formatRange(rentalRange(m))}</div><p>${m.checkedIn?'공간 도착을 기록했어요. 체험이 끝나면 만남을 완료해주세요.':'확정된 장소와 시간 안에서 만나요. 도착 기록은 위치를 수집하지 않아요.'}</p>`:''}<div class="actions"><button class="btn" data-action="read" data-id="${b.id}">책 다시 읽기</button>${m.status==='requested'?(meetingRole==='mentor'?`<button class="btn primary" data-action="accept" data-id="${m.id}">신청 수락</button><button class="btn" data-action="decline" data-id="${m.id}">거절하기</button>`:`<button class="btn" data-action="cancel-meeting" data-id="${m.id}">신청 취소·일정 변경</button>`):''}${m.status==='confirmed'?`${meetingRole==='mentor'?`<button class="btn" data-action="rental-period" data-id="${m.id}">대여 기간 변경</button>`:''}${!m.checkedIn?`<button class="btn primary" data-action="checkin" data-id="${m.id}">도착 기록 체험</button>`:`<button class="btn primary" data-action="complete" data-id="${m.id}">만남 완료 체험</button>`}<button class="btn" data-action="cancel-meeting" data-id="${m.id}">만남 취소</button>`:''}${m.status==='completed'?`<button class="btn" data-action="review" data-id="${m.id}">${reviewFor(m)?'후기·기록 수정':'후기·기록 쓰기'}</button><button class="btn primary" data-action="followup" data-id="${m.id}">후속 만남 신청 ${icon('arrow')}</button>`:''}${['confirmed','completed'].includes(m.status)?`<button class="btn" data-action="report" data-id="${b.id}">불편 신고</button>`:''}</div>${m.status==='completed'?reviewSummary(m):''}</div></article>`}
function updateMeeting(id,status){const m=state.meetings.find(m=>m.id===id);if(!m)return;if(status==='confirmed'&&m.status!=='requested')return;if(status==='completed'&&(!m.checkedIn||m.status!=='confirmed'))return;m.status=status;persist();render();toast({confirmed:'수락했어요. 이제 지정 장소에서 만날 수 있어요.',declined:'신청을 거절했어요.',completed:'대화를 마쳤어요. 원하면 후속 만남을 신청해요.',cancelled:'만남을 취소했어요. 다른 일정으로 다시 신청할 수 있어요.'}[status])}
function confirmMeeting(id,status){const m=state.meetings.find(m=>m.id===id);if(!m)return;const decline=status==='declined';openModal(decline?'신청 거절':'신청·만남 취소',`<div class="modal-body"><h3>${decline?'이번 신청을 거절할까요?':'이 만남을 취소할까요?'}</h3><p>${decline?'이야기할 범위나 일정이 맞지 않으면 거절할 수 있어요.':'취소 후 사람책에서 다른 일정으로 새로 신청할 수 있어요. 상대방에게 실제 알림이 전송되지는 않아요.'}</p><div class="actions"><button class="btn" data-action="close">돌아가기</button><button class="btn danger" data-action="confirm-status" data-id="${id}" data-value="${status}">${decline?'거절하기':'취소하기'}</button></div></div>`)}
function studio(){const d=state.draft;return `<div class="page-heading"><div class="eyebrow">WRITE YOUR OWN STORY</div><h1>당신도 한 권의 책이에요.</h1><p>완성된 전문가가 아니어도, 탐구하고 있는 지금의 경험을 들려주세요.</p></div><div class="studio-grid"><section class="panel"><h2>어떤 이야기를 나누고 싶나요?</h2><p>스펙 대신 계기와 시행착오, 지금의 질문을 담아주세요.</p><form id="studio-form"><div class="form-grid"><label class="field"><span>책에 표시할 별명</span><input name="name" maxlength="16" value="${esc(d.name||'')}" placeholder="예: 초록 (실명은 적지 마세요)" required></label><label class="field"><span>나를 소개하는 한 줄</span><input name="affiliation" maxlength="45" value="${esc(d.affiliation||'')}" placeholder="예: 진로를 탐색하는 대학생" required><small>체험용 소개만 적어요. 실제 소속 확인은 운영 단계에서 별도로 진행해요.</small></label></div><label class="field"><span>함께 이야기할 직업·흥미 분야</span><select name="category" required><option value="">분야를 골라주세요</option>${categories.slice(1).map(c=>`<option ${(typeof fieldGroup==='function'?fieldGroup(d.category)?.name:normalizeField(d.category))===c?'selected':''}>${c}</option>`).join('')}</select><small>대표 경험에 맞는 분야를 골라요. 정하기 어렵다면 ‘아직 모르겠어요’로 시작해도 괜찮아요.</small></label><label class="field"><span>어떻게 이 관심사를 만나게 됐나요?</span><textarea name="origin" required maxlength="1200" placeholder="작은 계기나 기억에 남는 순간을 적어주세요.">${esc(d.origin||'')}</textarea></label><label class="field"><span>어떤 시행착오나 고민이 있었나요?</span><textarea name="challenge" required maxlength="1200" placeholder="잘되지 않았던 경험도 좋은 이야기가 돼요.">${esc(d.challenge||'')}</textarea></label><label class="field"><span>지금은 무엇을 탐구하고 있나요?</span><textarea name="now" required maxlength="1200" placeholder="정답 대신, 지금 하고 있는 시도나 질문을 적어주세요.">${esc(d.now||'')}</textarea></label><div class="draft-tools"><button class="btn soft" type="button" data-action="assist">${icon('spark')}AI 작성 도우미 체험</button><span>입력한 답변만 문장으로 정리해요.</span></div><div class="notice">작성 도우미는 규칙 기반 체험이에요. AI API 연결이나 소속·경험의 사실 확인은 하지 않아요. 초안을 직접 고친 뒤 책에 담아주세요.</div><label class="field"><span>책 제목</span><input name="title" maxlength="48" value="${esc(d.title||'')}" placeholder="나의 이야기에 어울리는 제목" required></label><label class="field"><span>나의 이야기 원고</span><textarea name="story" style="min-height:240px" maxlength="5000" required placeholder="직접 쓰거나 위의 작성 도우미로 초안을 만들어보세요.">${esc(d.story||'')}</textarea></label><label class="field"><span>함께 나눌 수 있는 이야기</span><input name="help" maxlength="160" value="${esc(d.help||'')}" placeholder="예: 전공을 고르며 했던 고민, 작은 프로젝트 경험" required></label><label class="field"><span>경험 나눔의 범위와 한계</span><input name="boundary" maxlength="200" value="${esc(d.boundary||'전문 진단·상담, 합격·취업 보장, 유료 모집은 하지 않아요.')}" required></label><label class="checkline"><input type="checkbox" name="reviewed" required><span>원고를 직접 읽고 수정했으며, 허위 경력이나 타인의 개인정보를 담지 않았어요. 이 책은 내 브라우저에만 등록되는 체험용 책이에요.</span></label><div class="actions"><button class="btn" type="button" data-action="save-draft">초안 저장</button><button class="btn" type="button" data-action="preview-draft">미리 읽기</button><button class="btn primary" type="submit">내 사람책 등록 ${icon('arrow')}</button></div><p id="studio-message" class="pill-note" role="status">${state.published.length?`내가 등록한 체험용 책 ${state.published.length}권 · 등록 후에도 소속 확인 전 상태예요.`:'실제 공개·소속 확인·멘토 승인은 진행되지 않아요.'}</p></form></section><aside class="studio-aside">${cover({id:'own-preview',name:d.name||'나',title:'나의 경험이\n누군가의\n힌트가 되도록',subtitle:'지금의 나를 담은 한 권',color:0})}<p>01. 작은 계기에서 시작해요.<br>02. 시행착오도 함께 담아요.<br>03. 지금의 질문을 들려주세요.</p><div class="notice">이용자가 책과 대화 상대를 고르고, 운영자는 신뢰 확인과 안전 대응을 맡아요.</div></aside></div>`}
function captureDraft(){const f=$('#studio-form');if(!f)return null;const raw=Object.fromEntries(new FormData(f));delete raw.reviewed;state.draft=raw;persist();return raw}
function assist(){const d=captureDraft();if(!d)return;if(!d.origin?.trim()||!d.challenge?.trim()||!d.now?.trim()){toast('계기, 시행착오, 지금의 질문을 먼저 적어주세요.');return}const f=$('#studio-form');f.elements.title.value=d.title||`${d.name||'나'}의 아직 쓰는 중인 이야기`;f.elements.story.value=`작은 계기에서 시작했어요\n\n${d.origin.trim()}\n\n잘되지 않았던 순간도 있었어요\n\n${d.challenge.trim()}\n\n아직 쓰는 중인 다음 페이지\n\n${d.now.trim()}`;f.elements.reviewed.checked=false;captureDraft();$('#studio-message').textContent='작성 도우미가 답변을 원고로 정리했어요. 실제 AI 호출 없이 입력한 문장만 사용했어요. 내용을 확인하고 자유롭게 고쳐주세요.';toast('초안을 정리했어요. 나의 말투로 다듬어주세요.');f.elements.story.focus()}
function draftBook(d,id='own-preview'){return {id,taxonomyVersion:2,classCode:classificationOf({category:d.category}).code,name:d.name||'나',affiliation:d.affiliation||'소개 작성 중',title:d.title||'아직 쓰는 중인 이야기',subtitle:'지금의 나를 담은 한 권',color:0,category:d.category||'아직 탐색 중',tags:['나의 경험','탐구 중'],quote:d.title||'나의 다음 페이지를 함께 읽어요.',chapters:[['지금까지의 나, 그리고 다음 페이지',d.story||'아직 원고가 비어 있어요.']],help:d.help||'작성 중',boundary:d.boundary||'경험 나눔의 범위를 작성해주세요.'}}
function guide(){return `<div class="page-heading"><div class="eyebrow">A KIND & SAFE LIBRARY</div><h1>편안한 대화를 위한 약속.</h1><p>자유롭게 고르고, 함께 동의하고, 안전하게 만나요.</p></div><div class="settings-grid"><section class="panel"><h3>체험용 앱 안내</h3><p>사람책과 멘토, 장소는 모두 가상 예시예요. 회원가입·학생 인증·게시판·채팅도 모의 기능이며 실제 모집·신청·메시지 전송은 없어요. 작성한 책과 신청은 이 브라우저에만 저장되며 다른 기기와 공유되지 않아요.</p><div class="stats"><div><strong>${state.saved.length}</strong><span>저장한 사람책</span></div><div><strong>${state.meetings.length}</strong><span>체험한 만남</span></div></div><button class="btn" data-action="onboarding">도입 화면 다시 보기</button></section><section class="panel"><h3>자유로운 교류와 운영자의 역할</h3><ul><li>이용자가 책과 상대를 직접 고르고 신청해요.</li><li>멘토와 멘티가 수락·취소·후속 만남을 결정해요.</li><li>운영자는 멘토 확인, 공간 협력, 신고 대응에 집중해요.</li><li>시범 운영은 협력기관과 확인된 멘토를 기반으로 무료·소규모로 시작해요.</li></ul></section><section class="panel"><h3>안전하게 이야기 나누기</h3><ul><li>확보된 공공·청소년 시설과 담당자 상주 시간만 이용해요.</li><li>집·차량·개인 사무실이나 별도 장소로 이동하지 않아요.</li><li>개인 연락처, 학교, 집 주소, 민감한 이야기를 공개하지 않아요.</li><li>불편하면 대화를 멈추고 시설 담당자에게 도움을 요청해요.</li><li>이 앱은 전문 진단·치료·법률 상담을 제공하지 않아요.</li></ul></section><section class="panel"><h3>회원가입·학생 인증·대화 체험</h3><p>회원증과 학생 인증 표시는 이 브라우저의 모의 상태예요. 학교 이메일 발송·재학 서류 검증·실제 상대와의 채팅은 연결하지 않았어요. 공개 후기와 개인 상담 요약은 따로 보관해요.</p><button class="btn" data-action="account">회원증·학생 인증 보기</button></section><section class="panel"><h3>AI와 개인정보</h3><p>책 추천은 관심사에 따른 순서 정렬이고, 작성 도우미는 입력한 답변을 정리하는 체험이에요. 외부 AI 서비스에는 보내지 않아요. 실제 서비스에서는 연령에 맞는 동의 절차, 최소한의 정보 수집, 멘토 확인과 신고 대응 체계를 마련해야 해요.</p><button class="btn" data-action="interests">관심사 변경</button></section><section class="panel"><h3>사서·1:1 상담</h3><p>이용 방법이나 만남 일정, 불편한 경험을 사서에게 문의하는 화면을 체험해요.</p><button class="btn" data-action="help">사서 연락처와 상담 보기</button></section><section class="panel"><h3>숨긴 책과 체험 신고</h3><p>숨긴 사람책 ${state.blocked.length}권 · 체험 신고 ${state.reports.length}건<br>신고는 브라우저 기록이며 실제 담당자에게 전달되지 않아요. 실제 긴급 상황은 현장 담당자나 긴급 신고 체계를 이용해야 해요.</p><button class="btn" data-action="unblock" ${!state.blocked.length?'disabled':''}>숨긴 책 모두 다시 보기</button></section><section class="panel"><h3>체험 데이터 관리</h3><p>${storageOK?'이 브라우저에 체험 내역을 저장하고 있어요.':'브라우저 저장이 제한되어 내역이 유지되지 않을 수 있어요.'} 공용 기기를 사용했다면 체험 후 지워주세요. 초기화하면 작성한 책과 초안, 신청·상담 기록, 관심사도 지워져요.</p><button class="btn danger" data-action="reset">내 체험 데이터 초기화</button></section></div>`}
function report(id){openModal('불편한 경험 알리기',`<form id="report-form" class="modal-body" data-book="${id}"><h3>대화를 멈춰도 괜찮아요.</h3><p>신고는 가상으로 기록되며 운영자에게 전달되지 않아요. 실제 상황에서는 가까운 시설 담당자에게 즉시 도움을 요청해주세요.</p><label class="field"><span>어떤 점이 불편했나요?</span><select name="reason" required><option value="">이유를 골라주세요</option><option>부적절한 말이나 행동</option><option>개인 연락처·외부 만남 요구</option><option>허위 정보·상업적 권유</option><option>기타 불편한 경험</option></select></label><label class="field"><span>설명 <small>선택 · 실제 개인정보는 적지 마세요.</small></span><textarea name="detail" maxlength="500"></textarea></label><label class="checkline"><input type="checkbox" name="hide" checked><span>이 사람의 책도 함께 숨길게요.</span></label><div class="actions"><button type="button" class="btn" data-action="close">돌아가기</button><button class="btn primary" type="submit">신고 기록 체험</button></div></form>`)}

// Date-only ranges are inclusive. Public rental labels never expose the mentee.
function dayISO(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function validDay(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v||''))return false;const d=new Date(v+'T12:00:00');return !isNaN(d)&&dayISO(d)===v}
function scheduledDay(m){
 if(validDay(m.meetingDate))return m.meetingDate;
 const match=String(m.slot||'').match(/(\d+)월\s*(\d+)일/);if(!match)return dayISO(new Date(m.created||Date.now()));
 const created=new Date(m.created||Date.now());let year=created.getFullYear();if(created.getMonth()===11&&Number(match[1])===1)year++;
 return `${year}-${match[1].padStart(2,'0')}-${match[2].padStart(2,'0')}`;
}
function rentalRange(m){const fallback=scheduledDay(m);return {start:validDay(m.rentalStart)?m.rentalStart:fallback,end:validDay(m.rentalEnd)?m.rentalEnd:fallback}}
function formatDay(v){return v.replaceAll('-','.')}
function formatRange(r){return `${formatDay(r.start)} – ${formatDay(r.end)}`}
function bookRentals(id){const today=dayISO();return state.meetings.filter(m=>m.bookId===id&&m.status==='confirmed'&&rentalRange(m).end>=today).sort((a,b)=>rentalRange(a).start.localeCompare(rentalRange(b).start))}
function rentalConflict(id,start,end,exclude){return state.meetings.some(m=>m.id!==exclude&&m.bookId===id&&m.status==='confirmed'&&rentalRange(m).start<=end&&rentalRange(m).end>=start)}
function rentalBadge(id,compact=false){const list=bookRentals(id);if(!list.length)return '';const r=rentalRange(list[0]),active=r.start<=dayISO(),label=active?'대여중':'대여 예정';return `<span class="${compact?'rental-flag':'rental-badge'}"><strong>${label}</strong><span>${compact?`${r.start.slice(5).replace('-','.')}–${r.end.slice(5).replace('-','.')}`:formatRange(r)}</span>${list.length>1?`<small>외 ${list.length-1}건</small>`:''}</span>`}
function rentalPanel(id){const list=bookRentals(id);return list.length?`<section class="rental-panel" aria-label="사람책 대여 현황"><div>${icon('book')}<strong>이 사람책의 대여 일정</strong></div>${list.map(m=>{const r=rentalRange(m);return `<p><b>${r.start<=dayISO()?'대여중':'대여 예정'}</b><span>${formatRange(r)}</span></p>`}).join('')}<small>표시된 대여 기간과 겹치지 않는 날짜만 새 만남을 신청할 수 있어요.<br>책은 언제든 읽을 수 있어요. 대여 현황은 이 브라우저의 체험 기록이에요.</small></section>`:''}
function rentalForm(id){
 const m=state.meetings.find(x=>x.id===id);if(!m||!['requested','confirmed'].includes(m.status))return;
 const day=scheduledDay(m),r=rentalRange(m),editing=m.status==='confirmed';
 if(day<dayISO()){toast('이미 지난 일정이에요. 만남을 취소하고 새 일정으로 신청해주세요.');return}
 openModal(editing?'대여 기간 변경':'대여 기간 정하고 수락',`<form id="rental-form" class="modal-body" data-meeting="${m.id}"><div class="eyebrow">A BOOK OUT ON LOAN</div><h3>${esc(getBook(m.bookId)?.name||'사람책')}님의 대여 기간</h3><p>확정할 만남: ${esc(m.slot)}<br>멘토가 함께 이야기할 날짜를 포함해 기간을 정해요.</p><div class="form-grid"><label class="field"><span>대여 시작일</span><input type="date" name="start" required min="${dayISO()}" value="${r.start}"></label><label class="field"><span>대여 종료일</span><input type="date" name="end" required min="${dayISO()}" value="${r.end}"></label></div><div class="notice">시작일과 종료일을 모두 포함해요. 해당 기간은 다른 만남 신청에서 제외되며, 책 읽기는 계속 가능해요. 상대방의 이름은 서가에 표시하지 않아요.</div><p id="rental-error" class="form-error" role="alert"></p><div class="actions"><button type="button" class="btn" data-action="close">돌아가기</button><button type="submit" class="btn primary">${editing?'대여 기간 저장':'기간 확정·신청 수락'}</button></div></form>`)
}
function submitRental(form){
 if(!form.reportValidity())return;const m=state.meetings.find(x=>x.id===form.dataset.meeting);if(!m||!['requested','confirmed'].includes(m.status)){closeModal();toast('신청 상태가 바뀌었어요. 다시 확인해주세요.');return}
 const data=new FormData(form),start=data.get('start'),end=data.get('end'),day=scheduledDay(m),error=$('#rental-error');
 if(!validDay(start)||!validDay(end)||start>end){error.textContent='종료일은 시작일과 같거나 뒤여야 해요.';return}
 if(start<dayISO()||start>day||end<day){error.textContent='대여 기간에 확정할 만남 날짜가 포함되어야 해요. 지난 날짜로는 새로 수락할 수 없어요.';return}
 if(rentalConflict(m.bookId,start,end,m.id)){error.textContent='이미 확정된 다른 대여 기간과 겹쳐요. 기간을 바꿔주세요.';return}
 const editing=m.status==='confirmed';m.rentalStart=start;m.rentalEnd=end;m.meetingDate=day;m.status='confirmed';persist();closeModal();render();toast(editing?'대여 기간을 바꿨어요.':'수락했어요. 서가에 대여 기간이 표시돼요.');
}
function featuredShelves(){
 const groups=[{name:'베스트셀러',en:'BESTSELLER',desc:'먼저 펼쳐보고 싶은 이야기',ids:['b1','b3'],type:'popular'},{name:'우수도서',en:'LIBRARIAN’S PICKS',desc:'시행착오까지 솔직하게 담은 책',ids:['b2','b6'],type:'chosen'}];
 return `<section class="featured-section" aria-label="베스트셀러와 우수도서"><div class="featured-top"><span>오늘, 눈에 들어온 책</span><button data-action="featured-info">서가 선정 안내 ${icon('arrow')}</button></div><div class="featured-shelves">${groups.map(g=>`<section class="featured-shelf ${g.type}"><header><div><span class="eyebrow">${g.en}</span><h2>${g.name}<small>예시 서가</small></h2><p>${g.desc}</p></div><span class="feature-emblem" aria-hidden="true">${icon(g.type==='popular'?'heart':'spark')}</span></header><div class="featured-books">${g.ids.map(getBook).filter(b=>b&&!state.blocked.includes(b.id)).map(b=>`<button class="featured-book" data-action="read" data-id="${b.id}"><span class="featured-cover cover-${b.color}"><span>${esc(b.title.replaceAll('\n',' '))}</span><small>${esc(b.name)}의 이야기</small></span><span class="featured-caption">${esc(b.name)}<small>${esc(classificationOf(b).name)}</small></span>${rentalBadge(b.id)}</button>`).join('')||'<p class="featured-empty">숨긴 책은 이 서가에서도 보이지 않아요.</p>'}</div><div class="featured-ledge" aria-hidden="true"></div></section>`).join('')}</div></section>`;
}
function featuredInfo(){openModal('베스트셀러·우수도서 서가',`<div class="modal-body"><h3>좋은 이야기를 발견하는 또 하나의 길.</h3><h4>베스트셀러</h4><p>많이 읽힌 책을 모아 보여줄 공간이에요. 지금은 독서 기록을 집계하지 않아 가상 책을 예시로 배치했어요.</p><h4>우수도서</h4><p>경험이 구체적인지, 시행착오와 현재의 질문을 담았는지, 함께 나눌 범위가 분명한지를 기준으로 사서가 소개할 공간이에요. 현재는 선정 결과가 아닌 예시 서가예요.</p><div class="notice">실제 인기 순위·독자 평가·심사를 통과했다는 뜻은 아니에요.</div><button class="btn primary full" data-action="close">서가로 돌아가기</button></div>`)}
function helpDesk(){return `<div class="page-heading"><div class="eyebrow">YOUR LIBRARIAN, BY YOUR SIDE</div><h1>궁금할 때, 불편할 때.<br>사서가 함께할게요.</h1><p>이용 안내부터 안전에 관한 이야기까지, 혼자 고민하지 마세요.</p></div><div class="help-grid"><section class="librarian-card"><div class="librarian-seal">${icon('shield')}</div><span class="eyebrow">LIBRARY CARE DESK</span><h2>사서 · 보안담당자</h2><p>멘토 확인과 공간 이용 안내,<br>신고·불편 사항 대응을 맡아요.</p><div class="librarian-phone"><span>공개용 연락처 · 예시</span><strong>010-XXXX-XXXX</strong></div><dl><div><dt>상담 가능 시간</dt><dd>준비 중</dd></div><div><dt>이메일</dt><dd>준비 중</dd></div></dl><p class="contact-note">가상의 연락처이며 전화 연결은 제공하지 않아요.</p><div class="librarian-safety"><strong>만남 중 불편한 일이 생겼나요?</strong><p>대화를 멈추고 가까운 시설 담당자에게 도움을 요청하세요. 사람책의 ‘신고하기’에서 기록도 체험할 수 있어요.</p></div></section><section class="panel consultation-panel"><div class="eyebrow">ONE TO ONE</div><h2>사서와 1:1 상담</h2><p>이용 방법, 신청 일정, 불편한 경험을 편하게 남겨주세요.</p><form id="consult-form"><label class="field"><span>어떤 도움이 필요한가요?</span><select name="topic" required><option value="">상담 주제를 골라주세요</option><option>앱 이용 방법</option><option>만남 신청·일정</option><option>불편한 경험·안전</option><option>기타 문의</option></select></label><label class="field"><span>사서에게 남길 이야기</span><textarea name="message" required maxlength="1000" placeholder="체험용 내용을 적어주세요. 실제 이름·학교·연락처·민감한 정보는 적지 마세요."></textarea></label><div class="notice">접수와 대화 기록을 체험하는 화면이에요. 실제 담당자에게 전송되지 않으며, 내용은 이 브라우저에만 저장돼요.</div><button class="btn primary full" type="submit">상담 접수 체험 ${icon('arrow')}</button></form></section></div><section class="consultation-history"><div class="library-toolbar"><h2>나의 상담 기록 <span>${state.consultations.length}</span></h2><small>이 브라우저에만 보관</small></div>${state.consultations.length?state.consultations.map(c=>`<button class="consultation-row" data-action="consultation" data-id="${c.id}"><span class="consultation-symbol">${icon('book')}</span><span><strong>${esc(c.topic)}</strong><span class="consultation-preview">${esc(c.messages.at(-1)?.text||'')}</span><small>${formatDay(dayISO(new Date(c.created)))} · 체험 접수 · 실제 전송 안 됨</small></span>${icon('arrow')}</button>`).join(''):'<div class="consultation-empty">아직 남긴 이야기가 없어요.<br>위에서 상담 주제를 골라 첫 문의를 남겨보세요.</div>'}</section>`}
function consultationThread(id){const c=state.consultations.find(x=>x.id===id);if(!c)return;openModal('사서와 1:1 상담 · 체험',`<div class="modal-body"><div class="eyebrow">MY PRIVATE NOTE</div><h3>${esc(c.topic)}</h3><p class="pill-note">체험 접수 · 실제 담당자에게 전달되지 않아요.</p><div class="consultation-messages">${c.messages.map(m=>`<div class="consultation-message"><small>내가 남긴 이야기 · ${esc(new Date(m.at).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'}))}</small><p>${esc(m.text)}</p></div>`).join('')}<div class="consultation-system"><strong>${icon('shield')} 시스템 안내 · 체험</strong><p>입력한 내용을 이 브라우저에 기록했어요. 사서의 답변이나 실제 상담 접수는 이루어지지 않아요. 추가로 남길 이야기가 있다면 아래에 이어 적어보세요.</p></div></div><form id="consult-reply-form" data-consultation="${c.id}"><label class="field"><span>이어서 남길 이야기</span><textarea name="message" required maxlength="1000" placeholder="실제 개인정보 없이 체험용 내용을 적어주세요."></textarea></label><div class="actions"><button type="button" class="btn" data-action="close">상담 기록으로</button><button type="submit" class="btn primary">추가 기록 체험</button></div></form></div>`)}
function submitConsultation(form){if(!form.reportValidity())return;const data=new FormData(form),message=String(data.get('message')||'').trim();if(!message){toast('남길 이야기를 입력해주세요.');return}let c;if(form.id==='consult-form'){c={id:'c'+Date.now(),topic:String(data.get('topic')),created:Date.now(),messages:[]};state.consultations.unshift(c)}else c=state.consultations.find(x=>x.id===form.dataset.consultation);if(!c){toast('상담 기록을 찾을 수 없어요.');return}c.messages.push({text:message,at:Date.now()});persist();render();consultationThread(c.id);toast('상담 내용을 체험 기록에 저장했어요. 실제 전송은 없어요.')}

document.addEventListener('click',event=>{if(event.target.closest('.skip')){event.preventDefault();$('#main').focus();return}const button=event.target.closest('[data-action]');if(!button)return;const {action,id,value}=button.dataset;
 switch(action){
 case 'close':closeModal();break;
 case 'read':if(id==='own-preview'){readTemporaryDraft()}else readBook(id);break;
 case 'save':case 'save-reader':{state.saved=state.saved.includes(id)?state.saved.filter(x=>x!==id):[...state.saved,id];persist();render();if(action==='save-reader'){button.setAttribute('aria-pressed',state.saved.includes(id));$('span',button).textContent=state.saved.includes(id)?'책장에 담김':'책장에 담기'}toast(state.saved.includes(id)?'나의 책장에 담았어요.':'책장에서 꺼냈어요.');break}
 case 'filter':filter=value;render();break;
 case 'classification-guide':classificationGuide();break;
 case 'classification-select':filter=value;query='';closeModal();if(page==='library')render();else location.hash='library';break;
 case 'clear-search':query='';filter='전체';mentorCriteria={school:'전체',department:'전체',concern:'전체'};render();break;
 case 'random':{const list=allBooks().filter(b=>!state.blocked.includes(b.id));list.length?readBook(list[Math.floor(Math.random()*list.length)].id):toast('숨긴 책을 해제하면 다시 읽을 수 있어요.');break}
 case 'interests':interests();break;
 case 'choose-role':interests(value);break;
 case 'interest':selectedInterests=selectedInterests.includes(value)?selectedInterests.filter(x=>x!==value):[...selectedInterests,value];button.classList.toggle('active');button.setAttribute('aria-pressed',selectedInterests.includes(value));break;
 case 'finish-interests':finishOnboarding();break;
 case 'skip-interests':finishOnboarding(true);break;
 case 'skip-onboarding':onboardingRole='mentee';selectedInterests=[];finishOnboarding(true);break;
 case 'onboarding':onboarding();break;
 case 'library':location.hash='library';break;
 case 'demo-info':openModal('체험용 앱 안내',`<div class="modal-body"><h3>사람을 읽는 시간을 미리 경험해요.</h3><p>가상의 사람책과 공간으로 탐색·신청·수락 과정을 체험할 수 있어요. 작성한 내용은 이 브라우저에만 저장돼요. AI 작성·추천은 실제 AI API를 연결하지 않은 모의 기능이에요.</p><div class="notice">실제 이름·소속·연락처·학교·주소·민감한 정보는 입력하지 마세요. 실제 멘토 확인이나 협력시설 계약은 진행되지 않았어요.</div><button class="btn primary full" data-action="close">계속 둘러보기</button></div>`);break;
 case 'book-request':requestBook(id);break;
 case 'go-meetings':closeModal();location.hash='meetings';break;
 case 'meeting-role':meetingRole=value;render();break;
 case 'accept':case 'rental-period':rentalForm(id);break;
 case 'featured-info':featuredInfo();break;
 case 'help':closeModal();location.hash='help';break;
 case 'consultation':consultationThread(id);break;
 case 'decline':confirmMeeting(id,'declined');break;
 case 'cancel-meeting':confirmMeeting(id,'cancelled');break;
 case 'confirm-status':closeModal();updateMeeting(id,value);break;
 case 'checkin':{const m=state.meetings.find(m=>m.id===id);if(m?.status==='confirmed'){m.checkedIn=true;persist();render();toast('도착을 기록했어요. 위치 정보는 수집하지 않아요.')}break}
 case 'complete':updateMeeting(id,'completed');break;
 case 'followup':{const m=state.meetings.find(m=>m.id===id);if(m?.status==='completed')requestBook(m.bookId,m.id);break}
 case 'pause':state.paused=!state.paused;persist();render();toast(state.paused?'신규 신청받기 일시 중지 체험을 켰어요.':'신규 신청받기 체험을 재개했어요.');break;
 case 'assist':assist();break;
 case 'save-draft':captureDraft();toast('초안을 이 브라우저에 저장했어요.');break;
 case 'preview-draft':captureDraft();readTemporaryDraft();break;
 case 'report':report(id);break;
 case 'block':openModal('사람책 숨기기',`<div class="modal-body"><h3>이 사람의 책을 숨길까요?</h3><p>사람책 목록과 책장에서 보이지 않게 돼요. 기존 만남은 유지되며 나의 만남에서 별도로 취소할 수 있어요. 이용 안내에서 숨기기를 해제할 수 있어요.</p><div class="actions"><button class="btn" data-action="close">돌아가기</button><button class="btn primary" data-action="confirm-block" data-id="${id}">책 숨기기</button></div></div>`);break;
 case 'confirm-block':state.blocked=[...new Set([...state.blocked,id])];persist();closeModal();render();toast('이 사람의 책을 숨겼어요.');break;
 case 'unblock':state.blocked=[];persist();render();toast('숨긴 사람책을 다시 볼 수 있어요.');break;
 case 'reset':openModal('체험 데이터 초기화',`<div class="modal-body"><h3>처음부터 다시 둘러볼까요?</h3><p>내 책과 초안, 관심사, 책장, 모든 신청·상담·신고·질문·대화·후기·회원증 기록을 이 브라우저에서 지워요. 이 작업은 되돌릴 수 없어요.</p><div class="actions"><button class="btn" data-action="close">유지하기</button><button class="btn danger" data-action="confirm-reset">모두 지우고 새로 시작</button></div></div>`);break;
 case 'confirm-reset':state=defaults();filter='전체';query='';persist();closeModal();location.hash='library';render();onboarding();break;
 }
});
function readTemporaryDraft(){const b=draftBook(state.draft);openModal('내 책 미리 읽기',`<div class="modal-body"><div class="reader-intro">${cover(b)}<div><h3 class="reader-title">${esc(b.title)}</h3><p class="reader-person">${esc(b.name)} · ${esc(b.affiliation)}<br>미리보기 · 소속 확인 전</p></div></div><section class="chapter"><h3>지금 쓰고 있는 나의 이야기</h3><p>${esc(state.draft.story||'아직 이야기가 비어 있어요. 창을 닫고 원고를 작성해주세요.')}</p></section><div class="book-boundary"><h4>함께 나눌 수 있는 이야기</h4><p>${esc(b.help)}</p><h4 style="margin-top:14px">경험 나눔의 범위</h4><p>${esc(b.boundary)}</p></div><button class="btn primary full" data-action="close">원고로 돌아가기</button></div>`,true)}
document.addEventListener('submit',event=>{const f=event.target;if(!['search-form','request-form','studio-form','report-form','rental-form','consult-form','consult-reply-form'].includes(f.id))return;event.preventDefault();
 if(f.id==='search-form'){query=$('#search-input').value.trim();$('#results').innerHTML=libraryResults()}
 if(f.id==='request-form')submitRequest(f);
 if(f.id==='rental-form')submitRental(f);
 if(f.id==='consult-form'||f.id==='consult-reply-form')submitConsultation(f);
 if(f.id==='studio-form'){if(!f.reportValidity())return;const d=captureDraft();state.published.unshift(draftBook(d,'own-'+Date.now()));persist();render();toast('내 사람책을 등록했어요. 둘러보기에서 확인해요.');location.hash='library'}
 if(f.id==='report-form'){if(!f.reportValidity())return;const data=new FormData(f);state.reports.push({bookId:f.dataset.book,reason:data.get('reason'),detail:data.get('detail'),at:Date.now()});if(data.get('hide'))state.blocked=[...new Set([...state.blocked,f.dataset.book])];persist();closeModal();render();toast('체험 신고를 기록했어요. 실제 전달되지는 않아요.')}
});
document.addEventListener('input',event=>{if(event.target.id==='search-input'){query=event.target.value.trim();$('#results').innerHTML=libraryResults()}if(event.target.closest('#studio-form')){clearTimeout(window.draftTimer);window.draftTimer=setTimeout(captureDraft,500)}});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal()}});
$('#dialog').addEventListener('cancel',()=>{lastFocus?.isConnected&&lastFocus.focus()});
function route(){if(page==='studio')captureDraft();page=location.hash.replace('#','')||'library';if(!['library','shelf','meetings','studio','guide','help','community','account'].includes(page))page='library';render();window.scrollTo({top:0});}
layoutMedia.addEventListener('change',()=>{if(page==='studio')captureDraft();render()});
window.addEventListener('hashchange',route);route();
